import pathlib
import tempfile

from virt_lightning.domain_metadata import build_metadata
from virt_lightning.idisk import IDisk
from virt_lightning.init_system_compat import import_init_system


#
# Common code to generate a config drive and to attach it to a domain.
#
# The content of the config drive is generated by the init_system package.
#
class AuxiliaryConfigDriveDisk(IDisk):
    #: name of the init_system config drive flavor
    format_module = None

    def __init__(self, conn, storage, network):
        self.conn = conn
        self.storage = storage
        self.network = network

    def init(self, domain):
        init_system = import_init_system()
        metadata = build_metadata(domain, self.network)
        drive = init_system.get_config_drive(self.format_module, metadata)

        with tempfile.TemporaryDirectory() as base_temp_dir:
            temp_dir = pathlib.Path(base_temp_dir)
            cd_dir = temp_dir / "cd_dir"

            drive.build(cd_dir)

            cidata_file = temp_dir / f"{domain.name}-cidata.iso"
            drive.build_iso(cd_dir, cidata_file)

            cdrom = self.create(name=cidata_file.stem, size=1)
            with cidata_file.open("br") as fd:
                st = self.conn.newStream(0)
                cdrom.upload(st, 0, 1024 * 1024)
                st.send(fd.read())
                st.finish()
            return cdrom
